function me = ElementLHS4ConMass(nnpe,nqptv,wtq,bigN,detj)%  Called by MechMonics and by FitFieldDataWithHarmonics%% forms elemental LHS (mass) matrix for solving negative Laplacian and for%   determining expansion coefficients to data over grains of a polycrystaliend=nnpe;me = zeros(iend,iend);                                       for   k=1:1:nqptv       bigNqp = bigN(:,k)';                                      xkfac(k)=wtq(k)*detj(k);    me = me + xkfac(k)*(bigNqp' * bigNqp);      end